// Prebuild guard: fail loudly if the word match maps are missing.
//
// The maps (public/match-map/{locale}.vN.json) are generated by the top-level
// word-assets tool and are gitignored (large JSON), so a fresh checkout must run
// `just word-assets::match-map` before building. Runs automatically via the
// "prebuild" npm script.

import { readdirSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const LOCALES = ["en", "es"]
const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "public", "match-map")

function fail(message) {
  console.error(
    `\nERROR: ${message}\nBuild the word assets first:  just word-assets::match-map\n`,
  )
  process.exit(1)
}

let files = []
try {
  files = readdirSync(dir)
} catch {
  fail(`missing directory ${dir}`)
}

const missing = LOCALES.filter(
  (locale) => !files.some((name) => new RegExp(`^${locale}\\.v\\d+\\.json$`).test(name)),
)
if (missing.length > 0) {
  fail(`no match map for locale(s): ${missing.join(", ")}`)
}

console.log(`match-map guard: present for ${LOCALES.join(", ")}`)
